def footer(canvas, document):
    canvas.saveState()
    canvas.setStrokeColor(colors.HexColor("#cbd5e1"))
    canvas.line(18 * mm, 16 * mm, 192 * mm, 16 * mm)
    canvas.setFont("Helvetica", 8)
    canvas.setFillColor(colors.HexColor("#475569"))
    canvas.drawString(18 * mm, 11 * mm, "VANTAG | Offline demo-team manual | Controlled development workflow")
    canvas.drawRightString(192 * mm, 11 * mm, f"{document.page}")
    canvas.restoreState()


def main():
    OUTPUT.mkdir(parents=True, exist_ok=True)
    styles = getSampleStyleSheet()
    styles.add(ParagraphStyle(name="ManualTitle", fontName="Helvetica-Bold", fontSize=21, leading=25, textColor=colors.HexColor("#0f3b4a"), spaceAfter=12))
    styles.add(ParagraphStyle(name="ManualHeading", fontName="Helvetica-Bold", fontSize=11, leading=14, textColor=colors.HexColor("#0f766e"), spaceBefore=10, spaceAfter=4))
    styles.add(ParagraphStyle(name="ManualBody", fontName="Helvetica", fontSize=9.4, leading=13.5, spaceAfter=5, alignment=TA_LEFT))
    story = []
    html_sections = []
    for index, (title, paragraphs) in enumerate(SECTIONS):
        if index:
            story.append(PageBreak())
        story.append(Paragraph("VANTAG / RETAIL NAZAR", styles["ManualHeading"]))
        story.append(Paragraph(html.escape(title), styles["ManualTitle"]))
        section = [f'<section id="chapter-{index + 1}"><h2>{html.escape(title)}</h2>']
        for heading, text in paragraphs:
            story.append(Paragraph(html.escape(heading), styles["ManualHeading"]))
            story.append(Paragraph(html.escape(text).replace("\n", "<br/>"), styles["ManualBody"]))
            section.append(f'<h3>{html.escape(heading)}</h3><p>{html.escape(text).replace(chr(10), "<br>")}</p>')
        html_sections.append("".join(section) + "</section>")
    pdf = OUTPUT / f"{NAME}.pdf"
    SimpleDocTemplate(str(pdf), pagesize=A4, rightMargin=18 * mm, leftMargin=18 * mm, topMargin=16 * mm, bottomMargin=23 * mm, title="Vantag Offline Demo-Team Manual", author="Vantag").build(story, onFirstPage=footer, onLaterPages=footer)
    contents = "".join(f'<li><a href="#chapter-{index + 1}">{html.escape(title)}</a></li>' for index, (title, _) in enumerate(SECTIONS))
    page = '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vantag Offline Demo-Team Manual</title><style>body{font:16px/1.65 Segoe UI,Arial,sans-serif;color:#183041;background:#f2f6f8;margin:0}main{max-width:900px;margin:auto;padding:32px}section,header,nav{background:white;border:1px solid #d4e0e5;border-radius:12px;padding:26px;margin-bottom:24px}h1,h2{line-height:1.2;color:#0f3b4a}h3,a{color:#08796f}.warning{padding:18px;background:#fff4d6;border-left:4px solid #c58b19}p{overflow-wrap:anywhere}@media print{body{background:white}main{padding:0}nav{display:none}section{break-before:page;border:0;padding:0}a{color:inherit}}</style><main><header><h1>Offline demo-team manual</h1><p>Vantag / Retail Nazar | Windows local console | Agent 1.11.5 workflow</p><p class="warning">Controlled development testing only. Public offline installation remains under validation. This manual is not an installer or a guarantee of AI accuracy.</p><p>Save this HTML file for offline reading, or use the accompanying PDF. No internet assets are needed.</p></header><nav aria-label="Chapters"><ol>' + contents + '</ol></nav>' + "".join(html_sections) + '</main></html>'
    (OUTPUT / f"{NAME}.html").write_text(page, encoding="utf-8")
    print(f"Created {pdf.name} and offline-readable HTML; {len(SECTIONS)} chapters")


if __name__ == "__main__":
    main()
